244	  // THE PAGE TABLE — the one file that has to change when a page is added, and
245	  // the thing the nav and the router both read. Kept apart from router.tsx so
246	  // the mechanism stays untouched while the list of pages grows.
247	  "src/pages.tsx": `import type { PageDef } from "./router";
248	import Home from "./pages/Home";
249	
250	// Adding a page takes three steps and no config change:
251	//
252	//   1. src/pages/About.tsx — the page component.
253	//   2. An entry below, in the order it should appear in the nav.
254	//   3. about.html at the project root — a copy of index.html with its OWN
255	//      <title>, <meta name="description"> and OG tags, and data-page="/about"
256	//      on the root div. That file is why /about is a separate document a
257	//      search engine can rank on its own; without it the page is unreachable.
258	//
259	// Nested pages work the same way: services/boilers.html with
260	// data-page="/services/boilers".
261	export const PAGES: PageDef[] = [
262	  { path: "/", label: "Home", component: Home },
263	];
264	`,
265	
266	  // The shell every page renders inside: chrome that is shared (nav, footer)
267	  // wraps the one page component the document asked for.
268	  "src/App.tsx": `import { resolvePage } from "./router";
269	import { SiteNav } from "./components/SiteNav";
270	
271	export default function App({ page }: { page: string }) {
272	  const Page = resolvePage(page).component;
273	
274	  return (
275	    <div className="min-h-screen bg-white text-neutral-900">
276	      <SiteNav />
277	      <main>
278	        <Page />
279	      </main>
280	    </div>
281	  );
282	}
283	`,
