285	  "src/pages/Home.tsx": `import { Section } from "../components/ui/Section";
286	import { Button } from "../components/ui/Button";
287	
288	export default function Home() {
289	  return (
290	    <Section>
291	      <h1 className="text-4xl font-bold tracking-tight text-neutral-900">Welcome</h1>
292	      <p className="mt-4 text-lg text-neutral-600">
293	        Describe what you want built, and I'll take it from here.
294	      </p>
295	      <Button className="mt-6">Get started</Button>
296	    </Section>
297	  );
298	}
299	`,
