301	  // Site-level composition rather than a primitive: it reads the page table, so
302	  // a page added there appears in the nav on every page without a second edit.
303	  // Restyle it freely — the only part that must survive is that the links come
304	  // from navPages() and go through <Link>.
305	  "src/components/SiteNav.tsx": `import { Nav } from "./ui/Nav";
306	import { Link, navPages } from "../router";
307	
308	export function SiteNav() {
309	  const pages = navPages();
310	  if (pages.length < 2) return null; // a one-page site does not need a nav
311	
312	  return (
313	    <Nav>
314	      <div className="mx-auto flex max-w-5xl items-center gap-6 px-6 py-4 text-sm">
315	        {pages.map((page) => (
316	          <Link
317	            key={page.path}
318	            to={page.path}
319	            className="rounded text-neutral-600 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-neutral-900 aria-[current=page]:font-semibold aria-[current=page]:text-neutral-900"
320	          >
321	            {page.label}
322	          </Link>
323	        ))}
324	      </div>
325	    </Nav>
326	  );
327	}
328	`,
