340	type Props = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: Variant };
341	
342	export const Button = forwardRef<HTMLButtonElement, Props>(function Button(
343	  { variant = "primary", className = "", ...props },
344	  ref,
345	) {
346	  return (
347	    <button
348	      ref={ref}
349	      className={\`inline-flex items-center justify-center rounded-lg px-4 py-2.5 text-sm font-medium transition-colors \${variants[variant]} \${className}\`}
350	      {...props}
351	    />
352	  );
353	});
354	`,
355	
356	  "src/components/ui/Card.tsx": `import type { HTMLAttributes } from "react";
357	
358	export function Card({ className = "", ...props }: HTMLAttributes<HTMLDivElement>) {
359	  return (
360	    <div
361	      className={\`rounded-2xl border border-neutral-200 bg-white p-6 shadow-sm \${className}\`}
362	      {...props}
363	    />
364	  );
365	}
366	`,
367	
368	  "src/components/ui/Section.tsx": `import type { HTMLAttributes } from "react";
369	
370	export function Section({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
371	  return <section className={\`mx-auto max-w-5xl px-6 py-16 \${className}\`} {...props} />;
372	}
373	`,
374	
375	  "src/components/ui/Nav.tsx": `import type { HTMLAttributes } from "react";
376	
377	export function Nav({ className = "", ...props }: HTMLAttributes<HTMLElement>) {
378	  return (
379	    <nav
380	      className={\`sticky top-0 z-10 border-b border-neutral-200 bg-white/80 backdrop-blur \${className}\`}
381	      {...props}
382	    />
383	  );
384	}
