82	/**
83	 * Result shape for the API engine's `find_assets` tool. Trimmed to what the
84	 * model needs to paste — the full AssetMatch carries alternative encodings
85	 * that would multiply the token cost of every search for no benefit.
86	 */
87	export function formatMatchesForTool(matches: AssetMatch[]): string {
88	  if (matches.length === 0) {
89	    return "No assets matched. Try a broader term, or use a CSS gradient / inline SVG of your own.";
90	  }
91	  return matches
92	    .map((m) => [`### ${m.id} — ${m.name}`, m.usage, "", m.source].join("\n"))
93	    .join("\n\n---\n\n");
94	}
