180	/** `#abc`, `abc`, `#AABBCC` -> `#aabbcc`. Null when it is not a hex colour. */
181	export function normalizeHex(raw: unknown): string | null {
182	  if (typeof raw !== "string") return null;
183	  const v = raw.trim().replace(/^#/, "").toLowerCase();
184	  if (/^[0-9a-f]{3}$/.test(v)) return `#${v[0]}${v[0]}${v[1]}${v[1]}${v[2]}${v[2]}`;
185	  if (/^[0-9a-f]{6}$/.test(v)) return `#${v}`;
186	  return null;
187	}
188	
189	function channels(hex: string): [number, number, number] {
190	  return [
191	    parseInt(hex.slice(1, 3), 16),
192	    parseInt(hex.slice(3, 5), 16),
193	    parseInt(hex.slice(5, 7), 16),
194	  ];
195	}
196	
197	function toHex(r: number, g: number, b: number): string {
198	  const clamp = (n: number) => Math.max(0, Math.min(255, Math.round(n)));
199	  return `#${[r, g, b].map((n) => clamp(n).toString(16).padStart(2, "0")).join("")}`;
200	}
201	
202	/** Linear sRGB mix. t=0 returns `a`, t=1 returns `b`. */
203	function mix(a: string, b: string, t: number): string {
204	  const [ar, ag, ab] = channels(a);
205	  const [br, bg, bb] = channels(b);
206	  return toHex(ar + (br - ar) * t, ag + (bg - ag) * t, ab + (bb - ab) * t);
207	}
208	
209	/** WCAG 2.1 relative luminance. */
210	function luminance(hex: string): number {
211	  const [r, g, b] = channels(hex).map((c) => {
212	    const s = c / 255;
213	    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
214	  });
215	  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
216	}
217	
218	/** WCAG contrast ratio, 1..21. */
219	export function contrastRatio(a: string, b: string): number {
220	  const la = luminance(a);
221	  const lb = luminance(b);
222	  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
223	  return (hi + 0.05) / (lo + 0.05);
224	}
225	
226	const NEAR_BLACK = "#0b1120";
227	const NEAR_WHITE = "#ffffff";
228	
229	/**
230	 * The readable text colour to put ON `bg`. Near-black wins ties, because a
231	 * light-on-mid-tone pairing is the exact failure this codebase already carries
232	 * as a known accepted issue on its own brand gradient — the brand kit must not
233	 * reproduce it on a customer's site.
234	 */
235	export function readableInk(bg: string): string {
236	  const dark = contrastRatio(bg, NEAR_BLACK);
237	  const light = contrastRatio(bg, NEAR_WHITE);
238	  return dark >= light ? NEAR_BLACK : NEAR_WHITE;
239	}
240	
241	/**
242	 * A 50-950 tint/shade ramp anchored so that 500 IS the customer's colour.
243	 * Mixing in sRGB rather than a perceptual space is deliberate: it is
244	 * dependency-free, deterministic, and its output is a family of colours the
245	 * customer can recognise as theirs, which is the whole requirement.
246	 */
247	const RAMP_STEPS: [step: number, toward: "white" | "black", t: number][] = [
248	  [50, "white", 0.95],
249	  [100, "white", 0.9],
250	  [200, "white", 0.78],
251	  [300, "white", 0.62],
252	  [400, "white", 0.35],
253	  [500, "white", 0],
254	  [600, "black", 0.12],
255	  [700, "black", 0.28],
256	  [800, "black", 0.45],
257	  [900, "black", 0.6],
258	  [950, "black", 0.74],
259	];
260	
261	export function colorRamp(base: string): Record<number, string> {
262	  const out: Record<number, string> = {};
263	  for (const [step, toward, t] of RAMP_STEPS) {
264	    out[step] = t === 0 ? base : mix(base, toward === "white" ? NEAR_WHITE : "#000000", t);
265	  }
266	  return out;
267	}
