1173	/**
1174	 * Validate a raster data URI. Checks the declared type against the file's own
1175	 * magic bytes, so a mislabelled file is refused rather than shipped as a logo
1176	 * that renders as a broken-image icon on the customer's live site.
1177	 *
1178	 * image/svg+xml is deliberately NOT accepted here — an SVG has to go through
1179	 * sanitizeSvg(), and letting one in through the raster door would be a way to
1180	 * skip it.
1181	 */
1182	export function validateRasterDataUri(raw: unknown): RasterResult {
1183	  if (typeof raw !== "string") return { ok: false, reason: "That wasn't an image we could read." };
1184	  const uri = raw.trim();
1185	  if (uri.length > LOGO_LIMITS.RASTER_DATA_URI_MAX) {
1186	    return {
1187	      ok: false,
1188	      reason: `That logo is ${Math.round(uri.length / 1024)} KB encoded — the limit is ${
1189	        LOGO_LIMITS.RASTER_DATA_URI_MAX / 1024
1190	      } KB. Use an SVG, or a simpler image.`,
1191	    };
1192	  }
1193	  const match = /^data:(image\/(?:png|jpeg|webp));base64,([A-Za-z0-9+/]+={0,2})$/.exec(uri);
1194	  if (!match) {
