1196	  }
1197	  const mediaType = match[1] as RasterMediaType;
1198	
1199	  let bytes: Buffer;
1200	  try {
1201	    bytes = Buffer.from(match[2], "base64");
1202	  } catch {
1203	    return { ok: false, reason: "That image didn't decode." };
1204	  }
1205	  if (bytes.length < 16) return { ok: false, reason: "That image is empty." };
1206	
1207	  const sniffed = sniffImage(bytes);
1208	  if (sniffed !== mediaType) {
1209	    return { ok: false, reason: "That file's contents don't match its image type." };
1210	  }
1211	  return { ok: true, dataUri: uri, mediaType, bytes: bytes.length };
1212	}
